WITH changed AS (UPDATE app.customer_profiles SET display_name='csp1-synthetic-prefix',revision=revision+1 WHERE id='bf01dab5-2588-5135-846f-b546bb6d98a3'::uuid AND revision=0 RETURNING id,revision) SELECT jsonb_build_object('rows',count(*),'target',coalesce(bool_and(id='bf01dab5-2588-5135-846f-b546bb6d98a3'::uuid),false),'revision_one',coalesce(bool_and(revision=1),false)) FROM changed;
